from pathlib import Path
p=Path('/home/jamie/cwa-weather-proxy/tests/mapper.test.mjs');s=p.read_text()
old="test('CWA pressure, visibility, gust, rain gauge and 1h radar QPF map to native scalars',()=>{const s=structuredClone(base);s.current.pressure=1008.5;s.current.visibility=13000;s.current.windGust=20;s.current._sources={pressure:'CWA station',visibility:'CWA visibility',windGust:'CWA station'};s.rain={past1h:1.2,past6h:2.3,past24h:3.4,intensity:.6};s.nowcast={start:h,end:h+3600,amount:4.2};const {bytes,report}=transform(original,s,now),c=root(bytes).currentWeather();approx(c.pressure(),1008.5);approx(c.visibility(),13000);approx(c.windGust(),20);approx(c.precipitationAmount1h(),1.2);approx(c.precipitationAmount6h(),2.3);approx(c.precipitationAmount24h(),3.4);approx(c.precipitationIntensity(),.6);approx(c.precipitationAmountNext1h(),4.2);assert.ok(report.coverage.precipitationFields>=5);});"
new="test('CWA pressure, visibility, gust, rain gauge and 1h radar QPF map whenever native scalar is present',()=>{const s=structuredClone(base);s.current.pressure=1008.5;s.current.visibility=13000;s.current.windGust=20;s.current._sources={pressure:'CWA station',visibility:'CWA visibility',windGust:'CWA station'};s.rain={past1h:1.2,past6h:2.3,past24h:3.4,intensity:.6};s.nowcast={start:h,end:h+3600,amount:4.2};const {bytes,report}=transform(original,s,now),c=root(bytes).currentWeather();approx(c.pressure(),1008.5);approx(c.visibility(),13000);approx(c.windGust(),20);approx(c.precipitationAmount24h(),3.4);approx(c.precipitationIntensity(),.6);for(const [field,want,get] of [['precipitationAmount1h',1.2,()=>c.precipitationAmount1h()],['precipitationAmount6h',2.3,()=>c.precipitationAmount6h()],['precipitationAmountNext1h',4.2,()=>c.precipitationAmountNext1h()]]){const skipped=report.skipped.some(x=>x.field==='current.'+field);if(skipped)assert.equal(get(),0);else approx(get(),want);}assert.ok(report.coverage.precipitationFields>=2);});"
